import { Heatmap } from '@dreadnought/ui/react';
const columns = [{ id: 'mon', label: 'Пн' }, { id: 'tue', label: 'Вт' }];
const rows = [{ id: 'team', label: 'Команда' }];
const data = [{ column: 'mon', row: 'team', value: 0 }, { column: 'tue', row: 'team', value: 10 }];
export function Example() { return <Heatmap label="Закрытые задачи" columns={columns} rows={rows} data={data} domain={[0, 10]} />; }

import { Heatmap, useHeatmap } from '@dreadnought/ui/react';
const columns = [{id:'x',label:'X'}]; const rows = [{id:'a',label:'A'},{id:'b',label:'B'}]; const data = [{row:'a',column:'x',value:0},{row:'b',column:'x',value:10}];
function Controls() { const {page}=useHeatmap(); return <button disabled={page.page===page.count} onClick={()=>page.change(page.page+1)}>Следующая страница</button>; }
export function Example() { return <Heatmap label="Активность" columns={columns} rows={rows} data={data} pageSize={1}><Controls /><Heatmap.Legend /><Heatmap.Plot tooltipContent={({defaultContent})=><div>{defaultContent}</div>}>{({defaultContent})=><strong>{defaultContent}</strong>}</Heatmap.Plot><Heatmap.Table /><Heatmap.Pagination /><Heatmap.Empty /></Heatmap>; }
